buildResultUsage(message, modelId) {
    try {
        if (!message.usage) {
            return undefined;
        }
        const usage = {
            inputTokens: message.usage.input_tokens,
            cachedInputTokens: message.usage.cache_read_input_tokens,
            outputTokens: message.usage.output_tokens,
            totalCostUsd: message.total_cost_usd,
        };
        const modelContextWindowMaxTokens = this.recordModelUsage(message.modelUsage, modelId);
        if (this.contextWindowMaxTokens !== undefined) {
            usage.contextWindowMaxTokens = this.contextWindowMaxTokens;
        }
        else if (modelContextWindowMaxTokens !== undefined) {
            usage.contextWindowMaxTokens = modelContextWindowMaxTokens;
        }
        const activeResultUsageTokens = readActiveUsageTokens(message.usage) ??
            (this.completedResultTurns === 0 ? readLegacyResultUsageTokens(message.usage) : undefined);
        const usedTokens = this.streamUsedTokens() ?? activeResultUsageTokens ?? this.compactedContextWindowUsedTokens;
        if (usedTokens !== undefined) {
            usage.contextWindowUsedTokens = usedTokens;
        }
        return usage;
    }
    finally {
        this.compactedContextWindowUsedTokens = undefined;
        this.completedResultTurns += 1;
    }

createUsageUpdatedEvent(contextWindowUsedTokens) {
    const usage = {
        contextWindowUsedTokens,
    };
    if (this.contextWindowMaxTokens !== undefined) {
        usage.contextWindowMaxTokens = this.contextWindowMaxTokens;
    }
    return {
        type: "usage_updated",
        provider: "claude",
        usage,
    };
}

resolveThinkingConfig() {
    const thinkingOptionId = this.config.thinkingOptionId && this.config.thinkingOptionId !== "default"
        ? this.config.thinkingOptionId
        : undefined;
    assertClaudeThinkingOptionSupported(this.config.model, thinkingOptionId);
    if (thinkingOptionId === CLAUDE_DISABLED_THINKING_OPTION_ID) {
        return { thinking: { type: "disabled" }, effort: undefined, ultracode: false };
    }
    if (thinkingOptionId === CLAUDE_ULTRACODE_THINKING_OPTION_ID) {
        return {
            thinking: { type: "adaptive", display: "summarized" },
            effort: "xhigh",
            ultracode: true,
        };
    }
    if (thinkingOptionId && isClaudeThinkingEffort(thinkingOptionId)) {
        return {
            thinking: { type: "adaptive", display: "summarized" },
            effort: thinkingOptionId,
            ultracode: false,
        };
    }
    return { thinking: undefined, effort: undefined, ultracode: false };

export function toAgentUsage(tokenUsage) {
    const usage = toObjectRecord(tokenUsage);
    if (!usage)
        return undefined;
    const last = toObjectRecord(usage.last);
    const contextWindowMaxTokens = firstPositiveFiniteNumber(usage.model_context_window, usage.modelContextWindow);
    const contextWindowUsedTokens = firstPositiveFiniteNumber(last?.total_tokens, last?.totalTokens);
    return {
        inputTokens: typeof last?.inputTokens === "number" ? last.inputTokens : undefined,
        cachedInputTokens: typeof last?.cachedInputTokens === "number" ? last.cachedInputTokens : undefined,
        outputTokens: typeof last?.outputTokens === "number" ? last.outputTokens : undefined,
        ...(contextWindowMaxTokens !== undefined ? { contextWindowMaxTokens } : {}),
        ...(contextWindowUsedTokens !== undefined ? { contextWindowUsedTokens } : {}),
    };

handleTokenUsageUpdatedNotification(parsed) {
    this.latestUsage = toAgentUsage(parsed.tokenUsage);
    if (this.latestUsage) {
        this.notifySubscribers({
            type: "usage_updated",
            provider: CODEX_PROVIDER,
            usage: this.latestUsage,
        });
    }
}
